begin;
create schema ct;
create function ct.ok(v boolean,label text) returns void language plpgsql as $$ begin if v is distinct from true then raise exception 'ASSERT %',label;end if;end $$;
create function ct.no(cmd jsonb,label text,code text default null) returns void language plpgsql as $$ begin begin perform public.marketing_creative_command(cmd);exception when others then if code is not null and sqlstate<>code then raise exception 'ASSERT % expected % got %: %',label,code,sqlstate,sqlerrm;end if;return;end;raise exception 'ACCEPTED %',label;end $$;
create function ct.sqlno(cmd text,label text) returns void language plpgsql as $$ begin begin execute cmd;exception when others then return;end;raise exception 'ACCEPTED %',label;end $$;
create function ct.review_no(label text) returns void language plpgsql as $$ begin begin perform public.marketing_command(jsonb_build_object('action','submit_review','id','40000000-0000-4000-8000-000000000001','expected_version',(select version from public.marketing_content_items where id='40000000-0000-4000-8000-000000000001')));exception when others then if sqlstate<>'22023' then raise exception 'ASSERT % got %: %',label,sqlstate,sqlerrm;end if;return;end;raise exception 'ACCEPTED submit review %',label;end $$;
grant usage on schema ct to authenticated;grant execute on all functions in schema ct to authenticated;
insert into auth.users values('10000000-0000-4000-8000-000000000001','admin'),('10000000-0000-4000-8000-000000000002','member'),('10000000-0000-4000-8000-000000000003','viewer'),('10000000-0000-4000-8000-000000000004','outsider');
insert into public.profiles(id,email,status) select id,email,'active' from auth.users;
insert into public.user_roles values('10000000-0000-4000-8000-000000000001','Admin'),('10000000-0000-4000-8000-000000000002','PR Representative'),('10000000-0000-4000-8000-000000000003','Viewer'),('10000000-0000-4000-8000-000000000004','PR Leader');
insert into public.marketing_teams(id,name,creator_id) values('20000000-0000-4000-8000-000000000001','A','10000000-0000-4000-8000-000000000001'),('20000000-0000-4000-8000-000000000002','B','10000000-0000-4000-8000-000000000001');
insert into public.marketing_team_memberships(team_id,user_id) select '20000000-0000-4000-8000-000000000001',id from auth.users where email in('admin','member','viewer');
insert into public.marketing_campaigns(id,team_id,name,kind,creator_id) values('30000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','Campaign','seasonal','10000000-0000-4000-8000-000000000001');
insert into public.marketing_content_items(id,campaign_id,team_id,creator_id,title,content_line) values('40000000-0000-4000-8000-000000000001','30000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000002','Content','Sharing');
select ct.ok(not (select prosecdef from pg_proc where oid='public.marketing_creative_command(jsonb)'::regprocedure),'invoker');
select ct.ok(not has_function_privilege('service_role','public.marketing_creative_command(jsonb)','execute'),'no service role');
select ct.ok(not has_table_privilege('authenticated','public.marketing_assets','update'),'no direct DML');
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',true);
select set_config('ct.reserve',jsonb_build_object('action','reserve_asset','team_id','20000000-0000-4000-8000-000000000001','campaign_id',null,'title',repeat('T',180),'filename',repeat('f',251)||'.png','mime_type','image/png','byte_size',123,'width',16,'height',16,'reported_sha256',repeat('a',64),'provenance',repeat('p',2000),'author',repeat('a',200),'event',repeat('e',200),'tags',jsonb_build_array(repeat('t',80)))::text,true);
select ct.no(current_setting('ct.reserve')::jsonb||'{"title":true}','wrong type','22023');
select ct.no(current_setting('ct.reserve')::jsonb||'{"filename":"../x.png"}','filename','22023');
select ct.no(current_setting('ct.reserve')::jsonb||'{"team_id":"20000000-0000-4000-8000-000000000002"}','cross team','42501');
select set_config('ct.asset',public.marketing_creative_command(current_setting('ct.reserve')::jsonb)::text,true);
select ct.no(jsonb_build_object('action','complete_asset','id',current_setting('ct.asset')::jsonb->>'id','expected_version',1),'no object','22023');
select ct.sqlno('insert into storage.objects(bucket_id,name,metadata) values(''marketing-originals'',''arbitrary'', ''{}'')','upload bypass');
insert into storage.objects(bucket_id,name,metadata) values('marketing-originals',current_setting('ct.asset')::jsonb->>'storage_path','{"mimetype":"image/png","size":123}');
select set_config('ct.asset',public.marketing_creative_command(jsonb_build_object('action','complete_asset','id',current_setting('ct.asset')::jsonb->>'id','expected_version',1))::text,true);
select ct.ok(current_setting('ct.asset')::jsonb->>'rights'='needs_review','upload never approves');
select ct.no(jsonb_build_object('action','review_asset','id',current_setting('ct.asset')::jsonb->>'id','expected_version',2,'rights','approved','reason','review','allowed_channels',jsonb_build_array('facebook'),'valid_until',null),'member review','42501');
select set_config('ct.scene','{"schema_version":1,"width":1080,"height":1350,"format":"graphic_carousel","pages":[{"id":"50000000-0000-4000-8000-000000000001","background":"#FFFFFF","layers":[]}]}',true);
select set_config('ct.scene',jsonb_set(current_setting('ct.scene')::jsonb,'{pages,0,layers}',jsonb_build_array(jsonb_build_object('id','50000000-0000-4000-8000-000000000002','type','image','x',-12000,'y',12000,'width',12000,'height',1,'rotation',-180,'opacity',1,'locked',false,'asset_id',current_setting('ct.asset')::jsonb->>'id','fit','contain','role','logo')))::text,true);
select ct.no(jsonb_build_object('action','create_design','content_id','40000000-0000-4000-8000-000000000001','title','Test','scene',jsonb_set(current_setting('ct.scene')::jsonb,'{pages,0,layers,0,extra}','true')),'nested injection','22023');
select set_config('ct.design',public.marketing_creative_command(jsonb_build_object('action','create_design','content_id','40000000-0000-4000-8000-000000000001','title',repeat('D',180),'scene',current_setting('ct.scene')::jsonb))::text,true);
select ct.review_no('needs review asset');
select ct.ok((select version=2 from public.marketing_content_items where id='40000000-0000-4000-8000-000000000001'),'content invalidated');
select ct.no(jsonb_build_object('action','prepare_export','id',current_setting('ct.design')::jsonb->>'id','expected_version',1),'unreviewed rights','22023');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
select set_config('ct.asset',public.marketing_creative_command(jsonb_build_object('action','review_asset','id',current_setting('ct.asset')::jsonb->>'id','expected_version',2,'rights','approved','reason',repeat('r',2000),'allowed_channels',jsonb_build_array('facebook'),'valid_until',null))::text,true);
select public.marketing_creative_command(jsonb_build_object('action','prepare_export','id',current_setting('ct.design')::jsonb->>'id','expected_version',1));
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',true);
select set_config('ct.template',public.marketing_creative_command(jsonb_build_object('action','save_template','design_id',current_setting('ct.design')::jsonb->>'id','expected_version',1,'title',repeat('P',180),'scope','personal'))::text,true);
select set_config('ct.design',public.marketing_creative_command(jsonb_build_object('action','save_design','id',current_setting('ct.design')::jsonb->>'id','expected_version',1,'title','Edited','scene',current_setting('ct.scene')::jsonb))::text,true);
select ct.no(jsonb_build_object('action','save_design','id',current_setting('ct.design')::jsonb->>'id','expected_version',1,'title','stale','scene',current_setting('ct.scene')::jsonb),'stale save','40001');
select set_config('ct.design',public.marketing_creative_command(jsonb_build_object('action','restore_design','id',current_setting('ct.design')::jsonb->>'id','expected_version',2,'version_id',(select id from public.marketing_creative_versions where entity_type='design' and version=1 limit 1)))::text,true);
select ct.ok((select version=4 from public.marketing_content_items where id='40000000-0000-4000-8000-000000000001'),'restore invalidates content');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000003',true);
select ct.ok((select count(*)=0 from public.marketing_templates),'personal template hidden');
select ct.ok((select count(*)=0 from public.marketing_creative_versions where entity_type='template'),'personal history hidden');
select ct.no(jsonb_build_object('action','create_design','content_id','40000000-0000-4000-8000-000000000001','title','Viewer','scene',current_setting('ct.scene')::jsonb),'viewer write','42501');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000004',true);
select ct.ok((select count(*)=0 from public.marketing_designs),'outsider read');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
select public.marketing_creative_command(jsonb_build_object('action','review_asset','id',current_setting('ct.asset')::jsonb->>'id','expected_version',3,'rights','revoked','reason','Revoke','allowed_channels',jsonb_build_array(),'valid_until',null));
select ct.review_no('revoked image');
select ct.ok((select count(*)=0 from storage.objects),'revocation blocks subsequent file reads');
select ct.no(jsonb_build_object('action','prepare_export','id',current_setting('ct.design')::jsonb->>'id','expected_version',3),'revoked export','22023');
-- Graphics-only maximum scene exercises every text/shape bound and shared template transitions.
select set_config('ct.graphics',jsonb_set(current_setting('ct.scene')::jsonb,'{pages,0,layers}',jsonb_build_array(
jsonb_build_object('id','60000000-0000-4000-8000-000000000001','type','text','x',12000,'y',-12000,'width',1,'height',12000,'rotation',180,'opacity',0,'locked',true,'text',repeat('😀',1000),'font_size',240,'font_family','Georgia','fill','#AABBCC','align','right'),
jsonb_build_object('id','60000000-0000-4000-8000-000000000002','type','shape','x',0,'y',0,'width',1080,'height',1350,'rotation',0,'opacity',0.5,'locked',false,'fill','#000000','radius',500)))::text,true);
select ct.no(jsonb_build_object('action','save_design','id',current_setting('ct.design')::jsonb->>'id','expected_version',3,'title','Null enum','scene',jsonb_set(current_setting('ct.graphics')::jsonb,'{pages,0,layers,0,font_family}','null')),'null nested enum','22023');
select set_config('ct.design',public.marketing_creative_command(jsonb_build_object('action','save_design','id',current_setting('ct.design')::jsonb->>'id','expected_version',3,'title',repeat('X',180),'scene',current_setting('ct.graphics')::jsonb))::text,true);
select public.marketing_creative_command(jsonb_build_object('action','prepare_export','id',current_setting('ct.design')::jsonb->>'id','expected_version',4));
select set_config('ct.shared',public.marketing_creative_command(jsonb_build_object('action','save_template','design_id',current_setting('ct.design')::jsonb->>'id','expected_version',4,'title','Shared','scope','team'))::text,true);
select set_config('ct.shared',public.marketing_creative_command(jsonb_build_object('action','submit_template','id',current_setting('ct.shared')::jsonb->>'id','expected_version',1))::text,true);
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000003',true);
select ct.ok((select count(*)=0 from public.marketing_templates where id=(current_setting('ct.shared')::jsonb->>'id')::uuid),'pending shared hidden from Viewer');
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000001',true);
select ct.ok((select count(*)=1 from public.marketing_templates where id=(current_setting('ct.shared')::jsonb->>'id')::uuid),'manager sees pending shared queue');
select set_config('ct.shared',public.marketing_creative_command(jsonb_build_object('action','review_template','id',current_setting('ct.shared')::jsonb->>'id','expected_version',2,'decision','approve','reason','Reviewed'))::text,true);
select ct.no(jsonb_build_object('action','apply_template','template_id',current_setting('ct.shared')::jsonb->>'id','template_version',2,'design_id',current_setting('ct.design')::jsonb->>'id','expected_version',4),'stale template','40001');
select set_config('ct.design',public.marketing_creative_command(jsonb_build_object('action','apply_template','template_id',current_setting('ct.shared')::jsonb->>'id','template_version',3,'design_id',current_setting('ct.design')::jsonb->>'id','expected_version',4))::text,true);
select set_config('ct.variant',public.marketing_creative_command(jsonb_build_object('action','create_variant','id',current_setting('ct.design')::jsonb->>'id','expected_version',5,'title','Variant'))::text,true);
select ct.ok((select count(*)=2 from public.marketing_designs),'one default plus explicit variant');
select public.marketing_creative_command(jsonb_build_object('action','create_design','content_id','40000000-0000-4000-8000-000000000001','title','Idempotent','scene',current_setting('ct.graphics')::jsonb));
select ct.ok((select count(*)=2 from public.marketing_designs),'default idempotent');
-- Existing selected-idea evidence must remain current at export time.
reset role;
insert into public.marketing_sources(id,team_id,title,kind,excerpt,creator_id,status,version) values('70000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','Evidence','member_brief','Claim','10000000-0000-4000-8000-000000000001','approved',1);
insert into public.marketing_facts(id,team_id,source_id,claim,claim_type,category,status,creator_id) values('70000000-0000-4000-8000-000000000002','20000000-0000-4000-8000-000000000001','70000000-0000-4000-8000-000000000001','Claim','fact','general','verified','10000000-0000-4000-8000-000000000001');
insert into public.marketing_ideas(campaign_id,team_id,title,objective,hook,caption,content_line,rationale,evidence,origin,status,content_id,creator_id) values('30000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','Idea','','','','Sharing','','[{"fact_id":"70000000-0000-4000-8000-000000000002","fact_version":1,"source_id":"70000000-0000-4000-8000-000000000001","source_version":1}]','rule_based','selected','40000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001');
set local role authenticated;
select public.marketing_creative_command(jsonb_build_object('action','prepare_export','id',current_setting('ct.design')::jsonb->>'id','expected_version',5));
reset role;
update public.marketing_sources set status='revoked',version=2 where id='70000000-0000-4000-8000-000000000001';
set local role authenticated;
select ct.no(jsonb_build_object('action','prepare_export','id',current_setting('ct.design')::jsonb->>'id','expected_version',5),'revoked factual evidence blocks graphics export','22023');
select ct.review_no('stale selected idea evidence');
select set_config('ct.asset2',public.marketing_creative_command(current_setting('ct.reserve')::jsonb)::text,true);
insert into storage.objects(bucket_id,name,metadata) values('marketing-originals',current_setting('ct.asset2')::jsonb->>'storage_path','{"mimetype":"image/jpeg","size":123}');
select ct.no(jsonb_build_object('action','complete_asset','id',current_setting('ct.asset2')::jsonb->>'id','expected_version',1),'wrong mime metadata','22023');
reset role;
-- Only disposable-fixture superuser can alter timestamps/roles to simulate elapsed time and downgrades.
alter table public.marketing_assets disable trigger creative_guard;
update public.marketing_assets set created_at=now()-interval '21 minutes' where id=(current_setting('ct.asset2')::jsonb->>'id')::uuid;
alter table public.marketing_assets enable trigger creative_guard;
set local role authenticated;
select ct.sqlno(format('insert into storage.objects(bucket_id,name) values(%L,%L)','marketing-originals',current_setting('ct.asset2')::jsonb->>'storage_path'),'expired upload');
select ct.no(jsonb_build_object('action','complete_asset','id',current_setting('ct.asset2')::jsonb->>'id','expected_version',1),'expired completion','22023');
-- Isolated Foundation review transitions retain original version/revision behavior.
reset role;
update public.marketing_sources set status='approved',version=1 where id='70000000-0000-4000-8000-000000000001';
-- Restore photo to current scene through the authorized API; then simulate elapsed rights in fixture.
set local role authenticated;
select public.marketing_creative_command(jsonb_build_object('action','save_design','id',current_setting('ct.design')::jsonb->>'id','expected_version',5,'title','Review photo','scene',current_setting('ct.scene')::jsonb));
select ct.review_no('revoked current design among variants');
select public.marketing_creative_command(jsonb_build_object('action','review_asset','id',current_setting('ct.asset')::jsonb->>'id','expected_version',4,'rights','internal_only','reason','Internal only','allowed_channels',jsonb_build_array('internal'),'valid_until',null));
select ct.review_no('internal rights');
select public.marketing_creative_command(jsonb_build_object('action','review_asset','id',current_setting('ct.asset')::jsonb->>'id','expected_version',5,'rights','approved','reason','Facebook approved','allowed_channels',jsonb_build_array('facebook'),'valid_until',null));
reset role;
update public.marketing_assets set valid_until=now()-interval '1 second' where id=(current_setting('ct.asset')::jsonb->>'id')::uuid;
set local role authenticated;
select ct.review_no('expired rights');
reset role;
update public.marketing_assets set valid_until=null where id=(current_setting('ct.asset')::jsonb->>'id')::uuid;
set local role authenticated;
select set_config('ct.content_before',(select version::text from public.marketing_content_items where id='40000000-0000-4000-8000-000000000001'),true);
select public.marketing_command(jsonb_build_object('action','submit_review','id','40000000-0000-4000-8000-000000000001','expected_version',current_setting('ct.content_before')::integer));
select ct.ok((select publishing_status='in_review' and version=current_setting('ct.content_before')::integer+1 from public.marketing_content_items where id='40000000-0000-4000-8000-000000000001'),'eligible design submit bumps version');
select public.marketing_command(jsonb_build_object('action','request_changes','id','40000000-0000-4000-8000-000000000001','expected_version',current_setting('ct.content_before')::integer+1,'reason','Revise'));
select ct.ok((select publishing_status='changes_requested' and version=current_setting('ct.content_before')::integer+2 from public.marketing_content_items where id='40000000-0000-4000-8000-000000000001'),'request changes retained');
select public.marketing_creative_command(jsonb_build_object('action','save_design','id',current_setting('ct.design')::jsonb->>'id','expected_version',6,'title','Graphics default','scene',current_setting('ct.graphics')::jsonb));
select public.marketing_creative_command(jsonb_build_object('action','save_design','id',current_setting('ct.variant')::jsonb->>'id','expected_version',1,'title','Photo variant','scene',current_setting('ct.scene')::jsonb));
select public.marketing_creative_command(jsonb_build_object('action','review_asset','id',current_setting('ct.asset')::jsonb->>'id','expected_version',6,'rights','revoked','reason','Revoke variant image','allowed_channels',jsonb_build_array(),'valid_until',null));
select ct.review_no('all current variants checked even graphics default');
select set_config('ct.caption',public.marketing_command(jsonb_build_object('action','create_content','campaign_id','30000000-0000-4000-8000-000000000001','title','Caption only','caption','Copy','content_line','Sharing','assignee_id',null,'production_status','not_started','production_due_at',null,'review_due_at',null,'proposed_publish_at',null))::text,true);
select public.marketing_command(jsonb_build_object('action','submit_review','id',current_setting('ct.caption')::jsonb->>'id','expected_version',1));
select ct.ok((select publishing_status='in_review' and version=2 from public.marketing_content_items where id=(current_setting('ct.caption')::jsonb->>'id')::uuid),'caption-only path retained');
select ct.ok(not has_function_privilege('authenticated','marketing_private.creative_review_gate()','execute'),'gate has no client execute');
reset role;
update public.user_roles set role='Viewer' where user_id='10000000-0000-4000-8000-000000000002';
set local role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',true);
select ct.no(jsonb_build_object('action','prepare_export','id',current_setting('ct.design')::jsonb->>'id','expected_version',5),'downgrade','42501');
reset role;
select ct.sqlno('update public.marketing_creative_versions set version=900','immutable versions');
select ct.sqlno('delete from public.marketing_creative_audit_logs','immutable audits');
rollback;
